v=read('verification.json');m=read('metadata.json');p=read('publication.json');s=read('spec.json');f=read('fixtures.json');o=read('outcome-tables.json');c=read('catalogue-review.json')
fresh_cells=sum(t['fresh_proof_required'] for t in s['tasks'] for x in f['cells'] if x['case']==t['name'])
