def counts(scope,host,mode,comparison):return o['counts'].get('|'.join([scope,host,mode,comparison,'all']),{})
def table(rows,scope='fresh',expert=False):
 out=['| Target / boundary | Faster | Slower | Inconclusive |','|---|---:|---:|---:|']
 for label,host,mode,comparison in rows:
  d=counts(scope,host,mode,comparison);a,z=('Ink_faster','expert_faster') if expert else ('faster','slower')
  out.append(f'| {label} | {d.get(a,0)} | {d.get(z,0)} | {d.get("inconclusive",0)} |')
 return '\n'.join(out)
